SET @prov_c := '%s';
SET @id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET @b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

 CREATE TABLE IF NOT EXISTS s_asthma_relapse(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,

	target int(9) DEFAULT 0,
	target1 int(9) DEFAULT 0,
	result1 int(9) DEFAULT 0,
	result2 int(9) DEFAULT 0,

	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

DELETE FROM s_asthma_relapse WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_asthma_relapse

SELECT
@id,h.hoscode,concat(h.provcode,SUBSTR(CONCAT('00',h.distcode),-2),SUBSTR(CONCAT('00',h.subdistcode),-2),SUBSTR(CONCAT('00',h.mu),-2)) as areacode
,@send,DATE_FORMAT(now(),'%Y%m%d%H%i%s') as d_com,@b_year+543 as b_year
,COUNT(DISTINCT CONCAT(t.hospcode,'-',t.pid)) target
,COUNT(DISTINCT if(t.ics=1,CONCAT(t.hospcode,'-',t.pid),null)) target1

,COUNT(DISTINCT if(t.ics=1 AND t.nebulized_steroids=1 ,CONCAT(t.hospcode,'-',t.pid),null)) result1
,COUNT(DISTINCT if(t.ics<>1 AND t.nebulized_steroids=1 ,CONCAT(t.hospcode,'-',t.pid),null)) result2

FROM chospital h 
INNER JOIN t_asthma_relapse t ON h.hoscode=t.hospcode AND h.hostype IN(5,6,7,11,15)
INNER JOIN t_person_db p ON t.HOSPCODE=p.HOSPCODE AND t.PID=p.PID
GROUP BY h.hoscode;
